import * as React from 'react';
import * as HorizontalScrollerPrimitive from '@exhuma/core';
import { clsx } from 'clsx';

export interface HorizontalScrollerProps extends React.ComponentPropsWithoutRef<typeof HorizontalScrollerPrimitive.HorizontalScroller> {
  className?: string;
}

export const HorizontalScroller = React.forwardRef<HTMLDivElement, HorizontalScrollerProps>(
  ({ className, children, ...props }, ref) => (
    <HorizontalScrollerPrimitive.HorizontalScroller
      ref={ref}
      className={clsx(
        'relative overflow-hidden w-full py-8',
        className
      )}
      {...props}
    >
      {children}
    </HorizontalScrollerPrimitive.HorizontalScroller>
  )
);
HorizontalScroller.displayName = 'HorizontalScroller';

