import { Component, JSX, splitProps } from 'solid-js';
import * as HorizontalScrollerPrimitive from '@exhuma/core';

export interface HorizontalScrollerProps extends JSX.HTMLAttributes<HTMLDivElement> {
  [key: string]: unknown;
}

export const HorizontalScroller: Component<HorizontalScrollerProps> = (props) => {
  const [local, others] = splitProps(props, ['class', 'children']);
  return (
    <HorizontalScrollerPrimitive.HorizontalScroller
      class={`relative overflow-hidden w-full py-8 ${local.class ?? ''}`}
      {...others}
    >
      {local.children}
    </HorizontalScrollerPrimitive.HorizontalScroller>
  );
};

