import { HorizontalScroller } from '@exhuma/core';

class ExhumaHorizontalScrollerElement extends HTMLElement {
  connectedCallback() {
    this.classList.add('exhuma-horizontal-scroller');
    this.style.display = 'block';
  }
}

if (!customElements.get('exhuma-horizontal-scroller')) {
  customElements.define('exhuma-horizontal-scroller', ExhumaHorizontalScrollerElement);
}

react-native.code:
import React from 'react';
import { View, StyleSheet, type ViewProps } from 'react-native';
import * as HorizontalScrollerPrimitive from '@exhuma/core';

export interface HorizontalScrollerProps extends ViewProps {
  children?: React.ReactNode;
}

export function HorizontalScroller({ style, children, ...props }: HorizontalScrollerProps) {
  return (
    <View style={[styles.container, style]} {...props}>
      {children}
    </View>
  );
}

const styles = StyleSheet.create({
  container: {
    borderRadius: 16,
    borderWidth: 1,
    borderColor: '#e2e8f0',
    backgroundColor: '#ffffff',
    padding: 20,
    overflow: 'hidden',
  },
});

